325.description:
Se dă o expresie aritmetică formată din numere naturale, operatorii +, −, *, / și paranteze rotunde, fără spații. Ordinea operațiilor este cea obișnuită: întâi parantezele, apoi * și /, apoi + și −, iar operatorii cu aceeași prioritate se aplică de la stânga la dreapta. Împărțirea este întreagă, ca în C++: 7/2 = 3 și (0−7)/2 = −3.

Expresia respectă gramatica:
• expresie = termen, urmat de oricâte bucăți de forma + termen sau − termen;
• termen = factor, urmat de oricâte bucăți de forma * factor sau / factor;
• factor = un număr sau (expresie).

Se citește expresia. Scrie un program care calculează și afișează valoarea ei.

official_solution.code:
#include <iostream>
#include <string>
using namespace std;

string s;
int p = 0;

long long expresie();

long long factor() {
    if (s[p] == '(') {
        p++;              // '('
        long long v = expresie();
        p++;              // ')'
        return v;
    }
    long long v = 0;
    while (p < (int)s.size() && s[p] >= '0' && s[p] <= '9') {
        v = v * 10 + (s[p] - '0');
        p++;
    }
    return v;
}

long long termen() {
    long long v = factor();
    while (p < (int)s.size() && (s[p] == '*' || s[p] == '/')) {
        char op = s[p++];
        long long w = factor();
        if (op == '*') v *= w;
        else v /= w;
    }
    return v;
}

long long expresie() {
    long long v = termen();
    while (p < (int)s.size() && (s[p] == '+' || s[p] == '-')) {
        char op = s[p++];
        long long w = termen();
        if (op == '+') v += w;
        else v -= w;
    }
    return v;
}

int main() {
    cin >> s;
    cout << expresie() << "\n";
    return 0;
}

