#include <iostream>
using namespace std;

int v[100000];

void qs(int st, int dr) {
    int i = st, j = dr, p = v[(st + dr) / 2];
    while (i <= j) {
        while (v[i] < p) i++;
        while (v[j] > p) j--;
        if (i <= j) {
            swap(v[i], v[j]);
            i++;
            j--;
        }
    }
    if (st < j) qs(st, j);
    if (i < dr) qs(i, dr);
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> v[i];
    qs(0, n - 1);
    for (int i = 0; i < n; i++) cout << v[i] << " ";
    return 0;
}

