int v[100000], t[100000];

long long ms(int st, int dr) {
    if (st >= dr) return 0;
    int m = (st + dr) / 2;
    long long r = ms(st, m) + ms(m + 1, dr);
    int i = st, j = m + 1, k = st;
    while (i <= m || j <= dr) {
        if (j > dr || (i <= m && v[i] <= v[j])) t[k++] = v[i++];
        else {
            r += m - i + 1;
            t[k++] = v[j++];
        }
    }
    for (i = st; i <= dr; i++) v[i] = t[i];
    return r;
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << ms(0, n - 1);
    return 0;
}

