int main() {
    int q;
    cin >> q;
    string t, cmd;
    stack<pair<int, char>> st;
    while (q--) {
        cin >> cmd;
        if (cmd == "ADD") {
            char c;
            cin >> c;
            t += c;
            st.push({1, c});
        } else if (cmd == "DEL") {
            if (!t.empty()) {
                st.push({0, t.back()});
                t.pop_back();
            }
        } else if (!st.empty()) {
            auto u = st.top();
            st.pop();
            if (u.first == 1) t.pop_back();
            else t += u.second;
        }
    }
    if (t.empty()) cout << "GOL";
    else cout << t;
    return 0;
}

