int cmmdc(int a, int b) {
    while (b) {
        int r = a % b;
        a = b;
        b = r;
    }
    return a;
}

void simplifica(int &a, int &b) {
    int d = cmmdc(a, b);
    a /= d;
    b /= d;
}

int main() {
    int a, b;
    cin >> a >> b;
    simplifica(a, b);
    cout << a << " " << b;
    return 0;
}

