#include <iostream>
#include <stack>
using namespace std;
long long h[100001];
int st[100001], dr[100001];
int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> h[i];
    stack<int> s;
    for (int i = 0; i < n; i++) {
        while (!s.empty() && h[s.top()] >= h[i]) s.pop();
        st[i] = s.empty() ? -1 : s.top();
        s.push(i);
    }
    while (!s.empty()) s.pop();
    for (int i = n - 1; i >= 0; i--) {
        while (!s.empty() && h[s.top()] >= h[i]) s.pop();
        dr[i] = s.empty() ? n : s.top();
        s.push(i);
    }
    long long best = 0;
    for (int i = 0; i < n; i++) {
        long long a = h[i] * (dr[i] - st[i] - 1);
        if (a > best) best = a;
    }
    cout << best;
    return 0;
}

