#include <iostream>
using namespace std;
void sterge(int v[], int &n, int k) {
    for (int i = k - 1; i < n - 1; i++) v[i] = v[i + 1];
    n--;
}
int main() {
    int n, v[1000];
    cin >> n;
    for (int i = 0; i < n; i++) cin >> v[i];
    int i = 0;
    while (i < n) {
        if (v[i] < 0) sterge(v, n, i + 1);
        else i++;
    }
    if (n == 0) cout << "VID";
    for (int j = 0; j < n; j++) cout << v[j] << " ";
    return 0;
}

