#include <iostream>
#include <iomanip>
#include <algorithm>
using namespace std;
struct Ob { double g, v; };
Ob o[100000];
bool cmp(const Ob& a, const Ob& b) { return a.v * b.g > b.v * a.g; }
int main() {
    int n;
    double G, s = 0;
    cin >> n >> G;
    for (int i = 0; i < n; i++) cin >> o[i].g >> o[i].v;
    sort(o, o + n, cmp);
    for (int i = 0; i < n && G > 0; i++) {
        double ia = min(G, o[i].g);
        s += ia * o[i].v / o[i].g;
        G -= ia;
    }
    cout << fixed << setprecision(2) << s;
    return 0;
}

