#include <iostream>
using namespace std;
struct Fractie {
    long long a, b;
};
long long cmmdc(long long a, long long b) {
    while (b) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}
Fractie aduna(Fractie x, Fractie y) {
    Fractie r = {x.a * y.b + y.a * x.b, x.b * y.b};
    long long g = cmmdc(r.a, r.b);
    r.a /= g;
    r.b /= g;
    return r;
}
int main() {
    int n;
    Fractie s = {0, 1}, f;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> f.a >> f.b;
        s = aduna(s, f);
    }
    cout << s.a << " " << s.b;
    return 0;
}

