bool cmp(const Echipa& a, const Echipa& b) {
    if (a.p != b.p) return a.p > b.p;
    if (a.gd - a.gp != b.gd - b.gp) return a.gd - a.gp > b.gd - b.gp;
    return a.nume < b.nume;
}
int main() {
    int n, m, x, y;
    string a, b;
    map<string, int> id;
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        cin >> e[i].nume;
        id[e[i].nume] = i;
    }
    for (int k = 0; k < m; k++) {
        cin >> a >> b >> x >> y;
        Echipa &g = e[id[a]], &o = e[id[b]];
        g.gd += x; g.gp += y;
        o.gd += y; o.gp += x;
        if (x > y) g.p += 3;
        else if (x < y) o.p += 3;
        else { g.p++; o.p++; }
    }
    sort(e, e + n, cmp);
    for (int i = 0; i < n; i++) cout << e[i].nume << " " << e[i].p << " " << e[i].gd - e[i].gp << "\n";
    return 0;
}

