vector<int> aduna(const vector<int>& a, const vector<int>& b) {
    vector<int> c;
    int t = 0;
    for (size_t i = 0; i < a.size() || i < b.size() || t; i++) {
        int s = t;
        if (i < a.size()) s += a[i];
        if (i < b.size()) s += b[i];
        c.push_back(s % 10);
        t = s / 10;
    }
    return c;
}
